import sys, os, csv, json, gzip, io
from datetime import datetime, timedelta, timezone, date
from zoneinfo import ZoneInfo
from fractions import Fraction
from decimal import Decimal

def read_text(path):
    b = open(path, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')

def lines(path):
    return [l for l in read_text(path).splitlines() if l.strip()]

def local_to_utc(naive, tz, dst=None):
    """naive datetime -> epoch seconds. dst: None -> fold 0; True/False picks repeated occurrence."""
    if dst is not None:
        cands = []
        for fold in (0, 1):
            d = naive.replace(tzinfo=tz, fold=fold)
            cands.append(d)
        for d in cands:
            if bool(d.dst()) == dst:
                return int(d.timestamp())
    return int(naive.replace(tzinfo=tz, fold=0).timestamp())

def std_offset(tz, naive):
    for m in (0, 6, 1, 7, 3, 9):
        d = datetime(naive.year, m + 1 if m < 12 else 1, 1, tzinfo=tz)
        if not d.dst():
            return int(d.utcoffset().total_seconds())
    return int(datetime(naive.year, 1, 1, tzinfo=tz).utcoffset().total_seconds())

def parse_iso(s):
    s = s.strip()
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    return int(datetime.fromisoformat(s).timestamp())

def parse_abbr(path, tz):
    out = []
    hdr = None
    for row in csv.reader(lines(path)):
        if 'Badge' in row and 'Punch' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}
            continue
        if hdr is None: continue
        g = lambda n: row[hdr[n]].strip()
        mo, d, y = map(int, g('Date').split('/'))
        t = g('Time').upper()
        ap = None
        if t.endswith('AM') or t.endswith('PM'):
            ap = t[-2:]; t = t[:-2].strip()
        h, mi, s = map(int, t.split(':'))
        if ap:
            h = h % 12 + (12 if ap == 'PM' else 0)
        z = g('Zone').upper()
        dst = True if z.endswith('DT') else (False if z.endswith('ST') else None)
        ts = local_to_utc(datetime(y, mo, d, h, mi, s), tz, dst)
        out.append((g('Record'), g('Badge'), g('Punch').upper(), ts))
    return out

def parse_epoch(path, tz):
    out = []
    schema = 1
    for l in lines(path):
        o = json.loads(l)
        if 'schema' in o and 'punch_id' not in o and 'id' not in o:
            schema = o['schema']; continue
        if o.get('heartbeat'): continue
        if schema == 2:
            pid, emp, dr, ts = o['punch_id'], o['employee'], o['direction'], o['epoch_ms'] // 1000
        else:
            pid, emp, dr = o['id'], o['emp'], o['dir']
            ts = o['ts_ms'] // 1000 if 'ts_ms' in o else int(o['ts'])
        out.append((str(pid), emp, dr.upper(), int(ts)))
    return out

def parse_offset(path, tz):
    out = []
    rows = csv.reader(lines(path), delimiter=';')
    hdr = None
    for row in rows:
        if 'punch_id' in row:
            hdr = {n: i for i, n in enumerate(row)}; continue
        g = lambda n: row[hdr[n]]
        ev = g('event').lower()
        out.append((g('punch_id'), g('employee'), 'IN' if 'in' in ev else 'OUT', parse_iso(g('timestamp'))))
    return out

def parse_legacy(path, tz):
    out = []
    off = None
    for l in lines(path):
        if l[0] == 'H':
            o = l[13:18].strip()
            if o:
                sg = -1 if o[0] == '-' else 1
                off = sg * (int(o[1:3]) * 3600 + int(o[3:5]) * 60)
            else:
                off = None
        elif l[0] == 'D':
            pid = l[1:9]
            badge = 'E' + l[9:15].strip()
            dr = 'IN' if l[15] == 'I' else 'OUT'
            n = datetime.strptime(l[16:30], '%Y%m%d%H%M%S')
            o = off if off is not None else std_offset(tz, n)
            ts = int((n.replace(tzinfo=timezone.utc)).timestamp()) - o
            out.append((pid, badge, dr, ts))
    return out

def parse_de(path, tz):
    out = []
    hdr = None
    for l in lines(path):
        row = l.split('\t')
        if 'Ausweis' in row:
            hdr = {n.strip(): i for i, n in enumerate(row)}; continue
        g = lambda n: row[hdr[n]].strip()
        d, mo, y = map(int, g('Datum').split('.'))
        h, mi = map(int, g('Uhrzeit').split(':')[:2])
        z = g('Zeitzone').upper()
        dst = True if z == 'MESZ' else (False if z == 'MEZ' else None)
        ts = local_to_utc(datetime(y, mo, d, h, mi), tz, dst)
        out.append((g('Nr'), g('Ausweis'), 'IN' if g('Buchung').upper() == 'K' else 'OUT', ts))
    return out

def parse_localcsv(path, tz):
    out = []
    hdr = None
    for row in csv.reader(lines(path)):
        if 'employee_id' in row:
            hdr = {n: i for i, n in enumerate(row)}; continue
        g = lambda n: row[hdr[n]].strip()
        ts = local_to_utc(datetime.strptime(g('local_time'), '%Y-%m-%d %H:%M:%S'), tz)
        out.append((g('punch_ref'), g('employee_id'), g('direction').upper(), ts))
    return out

def parse_localjsonl(path, tz):
    out = []
    for l in lines(path):
        o = json.loads(l)
        p = o.get('punch')
        if not isinstance(p, dict): continue
        ts = local_to_utc(datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S'), tz)
        out.append((str(p['id']), p['badge'], p['type'].upper(), ts))
    return out

PARSERS = {'abbr-csv': parse_abbr, 'epoch-jsonl': parse_epoch, 'offset-csv': parse_offset,
           'legacy-fixed': parse_legacy, 'de-tsv': parse_de, 'local-csv': parse_localcsv,
           'local-jsonl': parse_localjsonl}

def rnd(ts, tz):
    off = int(datetime.fromtimestamp(ts, tz).utcoffset().total_seconds())
    r = (ts + off) % 360
    return ts + (360 - r if r >= 180 else -r)

def main(inp, outp):
    period = json.load(open(os.path.join(inp, 'period.json')))
    pstart = date.fromisoformat(period['start']); pend = date.fromisoformat(period['end'])
    cutoff = parse_iso(period['corrections_cutoff'])
    sites = {}
    for r in csv.DictReader(lines(os.path.join(inp, 'sites.csv'))):
        sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    emps = {}
    for r in csv.DictReader(lines(os.path.join(inp, 'employees.csv'))):
        emps[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in csv.DictReader(lines(os.path.join(inp, 'rates.csv'))):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Fraction(Decimal(r['hourly_rate'].strip()))))
    for v in rates.values(): v.sort()

    punches = {}   # (site,id) -> [emp, dir, ts]
    ever = set()
    for site, (tz, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d): continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                for pid, emp, dr, ts in PARSERS[fmt](os.path.join(root, fn), tz):
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for fn in os.listdir(cdir):
            p = os.path.join(cdir, fn)
            if os.path.isfile(p):
                for r in csv.DictReader(lines(p)):
                    corr.append({k: (v or '').strip() for k, v in r.items()})
    corr = [c for c in corr if parse_iso(c['issued_at']) <= cutoff]
    corr.sort(key=lambda c: (parse_iso(c['issued_at']), c['correction_id']))
    applied = 0
    for c in corr:
        k = (c['site'], c['punch_id'])
        a = c['action'].lower()
        if a == 'void':
            if k in punches: del punches[k]; applied += 1
        elif a == 'set':
            if k in punches: punches[k][2] = parse_iso(c['time']); applied += 1
        elif a == 'add':
            if k not in ever:
                ever.add(k)
                punches[k] = [c['employee'], c['type'].upper(), parse_iso(c['time'])]
                applied += 1

    per = {e: [] for e in emps}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in per:
            per[emp].append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    res = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0)) for e in emps}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)
    for e, pl in per.items():
        home = sites[emps[e]][0]
        wd = lambda t: datetime.fromtimestamp(t, home).date()
        pl.sort()
        kept = []
        for ts, _, site, pid, dr in pl:
            tz = sites[site][0]
            rt = rnd(ts, tz)
            if kept and kept[-1][1] == dr and ts - kept[-1][0] <= 300:
                if pstart <= wd(rt) <= pend: exc['duplicates_dropped'] += 1
                continue
            kept.append((ts, dr, rt, site))
        shifts = []
        pend_in = None
        def openit(p):
            if pstart <= wd(p[2]) <= pend: exc['open_shifts'] += 1
        for p in kept:
            if p[1] == 'IN':
                if pend_in: openit(pend_in)
                pend_in = p
            else:
                if pend_in and p[2] - pend_in[2] <= 16 * 3600:
                    shifts.append((pend_in, p))
                else:
                    if pend_in: openit(pend_in)
                    if pstart <= wd(p[2]) <= pend: exc['orphan_outs'] += 1
                pend_in = None
        if pend_in: openit(pend_in)
        items = []
        for i, o in shifts:
            w = wd(i[2])
            if not (pstart <= w <= pend): continue
            worked = max(0, (o[2] - i[2]) // 60)
            paid = worked - 30 if worked > 360 else worked
            tz = sites[i[3]][0]
            night = 0
            for t in range(i[2], o[2], 60):
                h = datetime.fromtimestamp(t, tz).hour
                if h >= 22 or h < 6: night += 1
            night = min(night, paid)
            items.append((i[2], w, paid, night))
        items.sort()
        daily = {}; weekly = {}
        r = res[e]
        for _, w, paid, night in items:
            used = daily.get(w, 0)
            dot = max(0, used + paid - 480) - max(0, used - 480)
            daily[w] = used + paid
            nd = paid - dot
            wk = w - timedelta(days=w.weekday())
            wu = weekly.get(wk, 0)
            wot = max(0, wu + nd - 2400) - max(0, wu - 2400)
            weekly[wk] = wu + nd
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rt_ in rates.get(e, []):
                if ef <= w: rate = rt_
            rate = rate or Fraction(0)
            pay = rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60
            r['shifts'] += 1; r['paid_minutes'] += paid; r['overtime_minutes'] += ot
            r['night_minutes'] += night; r['gross'] += pay
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    tg = 0
    out = {}
    for e, r in res.items():
        cents = int((r['gross'] * 100 + Fraction(1, 2)) // 1)
        tg += cents
        for k in tot: tot[k] += r[k]
        out[e] = {k: r[k] for k in tot}
        out[e]['gross'] = '%d.%02d' % divmod(cents, 100)
    tot['gross'] = '%d.%02d' % divmod(tg, 100)
    json.dump({'period': {'start': period['start'], 'end': period['end']}, 'employees': out,
               'exceptions': exc, 'totals': tot}, open(outp, 'w'), indent=1)

if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
